import{_ as h,o as t,c as i,a5 as a}from"./chunks/framework.Bf1r8NYr.js";const e=JSON.parse('{"title":"Bài 3 — Chuẩn dữ liệu: CDISC, FHIR và OMOP bổ trợ nhau","description":"","frontmatter":{},"headers":[],"relativePath":"course/module-3-standards/index.md","filePath":"course/module-3-standards/index.md"}'),c={name:"course/module-3-standards/index.md"};function u(o,n,r,g,s,l){return t(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="bai-3-—-chuan-du-lieu-cdisc-fhir-va-omop-bo-tro-nhau" tabindex="-1">Bài 3 — Chuẩn dữ liệu: CDISC, FHIR và OMOP bổ trợ nhau <a class="header-anchor" href="#bai-3-—-chuan-du-lieu-cdisc-fhir-va-omop-bo-tro-nhau" aria-label="Permalink to &quot;Bài 3 — Chuẩn dữ liệu: CDISC, FHIR và OMOP bổ trợ nhau&quot;">​</a></h1><p><strong>Mục tiêu:</strong> nói được mỗi chuẩn dùng để làm gì, và vì sao không chọn chỉ một chuẩn.</p><p><strong>Lớp kiểm soát bảo mật, đạo đức và pháp lý áp dụng xuyên suốt mọi giai đoạn của vòng đời dữ liệu.</strong></p><h2 id="noi-dung-chinh" tabindex="-1">Nội dung chính <a class="header-anchor" href="#noi-dung-chinh" aria-label="Permalink to &quot;Nội dung chính&quot;">​</a></h2><p>Ba chuẩn lớn nhất thường bị hiểu là đối thủ của nhau. Thực ra chúng bổ trợ nhau, mỗi chuẩn giải một bài toán khác:</p><ul><li><strong>CDISC (đặc biệt SDTM):</strong> chuẩn để <strong>nộp hồ sơ</strong> cho cơ quan quản lý. Dữ liệu thử nghiệm lâm sàng được chuyển thành dạng bảng chuẩn để FDA/EMA đọc được.</li><li><strong>FHIR (HL7):</strong> chuẩn để <strong>trao đổi lâm sàng theo thời gian thực</strong> giữa các hệ thống bệnh viện. FHIR R4 (2019) là bản dùng trong thực hành; R5 ban hành 26/03/2023; <strong>R6 chưa ban hành, đang trong giai đoạn ballot</strong>.</li><li><strong>OMOP CDM (OHDSI):</strong> mô hình dữ liệu chung để <strong>phân tích quần thể</strong> trên nhiều cơ sở dữ liệu. OMOP CDM v5.4 (09/2021) là bản tham chiếu. Mạng lưới OHDSI cuối 2025: 4.833 cộng tác viên ở 88 quốc gia, 544 nguồn dữ liệu ở 54 quốc gia, 974 triệu hồ sơ bệnh nhân duy nhất.</li></ul><p>Ba chức năng này bổ trợ nhau: CDISC/SDTM phục vụ nộp hồ sơ, FHIR phục vụ trao đổi lâm sàng, còn OMOP CDM phục vụ phân tích quần thể. Nghiên cứu LEGEND-HTN (Suchard và cộng sự, 2019) minh họa phân tích phân tán trên 4,9 triệu bệnh nhân; mã phân tích được chạy tại từng cơ sở và chỉ gửi thống kê tổng hợp.</p><p>SMART on FHIR là lớp ứng dụng chạy trên FHIR: ứng dụng bên thứ ba đọc/ghi dữ liệu EHR qua API chuẩn. FHIR Bulk Data API hỗ trợ xuất dữ liệu quần thể hàng loạt.</p><p><strong>Điểm cần nhớ:</strong> hỏi “nên dùng CDISC hay FHIR hay OMOP?” là hỏi sai. Hỏi đúng là: “dữ liệu này cần đi đâu — nộp hồ sơ, trao đổi lâm sàng, hay phân tích quần thể?”</p>',9)])])}const p=h(c,[["render",u]]);export{e as __pageData,p as default};
